    // j=2: C(2,2) * [m=0: C(0,0)*1*2^2*2!*2!/5!] = 1 * 1*1*4*4/120 = 16/120 = 2/15
    // Total = 2/5 + 2/15 = 6/15 + 2/15 = 8/15. Correct!
    //
    // Great, so the formula is:
    // Answer = l * Σ_{j=k}^{n} C(n,j) * Σ_{t=j}^{n} C(n-j, t-j) * (-1)^{t-j} * 2^t * (t!)² / (2t+1)!
    //
    // Let's precompute factorials and inverse factorials up to 2n+1.

    int maxN = 2 * n + 1;
    vector<long long> fact(maxN + 1), invfact(maxN + 1);
    fact[0] = 1;
    for (int i = 1; i <= maxN; i++) {
        fact[i] = fact[i - 1] * i % MOD;
    }
    invfact[maxN] = modinv(fact[maxN], MOD);
    for (int i = maxN; i >= 1; i--) {
        invfact[i - 1] = invfact[i] * i % MOD;
    }

    auto C = [&](int N, int K) -> long long {
        if (K < 0 || K > N) return 0;
        return fact[N] * invfact[K] % MOD * invfact[N - K] % MOD;
    };

    long long ans = 0;
    for (int j = k; j <= n; j++) {
        long long inner = 0;
        for (int t = j; t <= n; t++) {
            int m = t - j;
            long long term = C(n - j, m);
            if (m % 2 == 1) term = (MOD - term) % MOD; // (-1)^m
            term = term * modpow(2, t, MOD) % MOD;
            term = term * fact[t] % MOD * fact[t] % MOD;
            term = term * invfact[2 * t + 1] % MOD;
            inner = (inner + term) % MOD;
        }
        long long outer = C(n, j) * inner % MOD;
        ans = (ans + outer) % MOD;
    }

    ans = ans * (l % MOD) % MOD;

    cout << ans << endl;

    return 0;
}
