#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int MOD = 998244353;

ll modpow(ll a, ll b, ll mod) {
    ll res = 1;
    a %= mod;
    while (b) {
        if (b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

ll modinv(ll a, ll mod) {
    return modpow(a, mod - 2, mod);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    ll l;
    cin >> n >> k >> l;

    // Precompute factorials and inverse factorials up to 2n
    int maxN = 2 * n;
    vector<ll> fact(maxN + 1), invfact(maxN + 1);
    fact[0] = 1;
    for (int i = 1; i <= maxN; i++) {
        fact[i] = fact[i - 1] * i % MOD;
    }
    invfact[maxN] = modinv(fact[maxN], MOD);
    for (int i = maxN; i >= 1; i--) {
        invfact[i - 1] = invfact[i] * i % MOD;
    }

    auto C = [&](int N, int R) -> ll {
        if (R < 0 || R > N) return 0;
        return fact[N] * invfact[R] % MOD * invfact[N - R] % MOD;
    };

    // We need to compute the expected total length of intervals covered by at least k segments.
    // 
    // Consider a point x in [0, l]. The probability that a single random segment covers x is:
    // A segment is defined by two random points u, v in [0, l]. The segment covers x if x is between u and v.
    // P(x is covered by one segment) = P(min(u,v) <= x <= max(u,v))
    // = P(u <= x <= v) + P(v <= x <= u)
    // = (x/l) * ((l-x)/l) + ((l-x)/l) * (x/l)
    // = 2 * x * (l-x) / l^2
